head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.isFirstLoad = false;
scwin.delYn = false;
// 세션정보를 얻기위한 함수사용
scwin.Secugrp_id = "", scwin.Mkt_id = "", scwin.fr_bz_procs_no = "", scwin.Dd = "", scwin.p_Isur_cd = "", scwin.p_Isur_nm = "";
scwin.trsIdx; // insert, update 구분

scwin.getPar, scwin.setPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        const fnc = $c.frame.path("../").scwin.getPar; // Provider화면에서 fn_GetPar명칭으로 선언된 함수를 획득
        const arrPar = new Array();
        if (fnc !== undefined) {
            fnc(arrPar); // Provider화면의 callback함수를 호출하여 필요한 인수를 넘겨받는다.
            scwin.Secugrp_id = (arrPar.length >= 1 ? arrPar[0] : ""); // 증권그룹ID
            scwin.Mkt_id = (arrPar.length >= 2 ? arrPar[1] : ""); // 시장구분코드
            scwin.fr_bz_procs_no = (arrPar.length >= 3 ? arrPar[2] : ""); // 업무처리번호(수정시만 유효)
            scwin.Dd = (arrPar.length >= 4 ? arrPar[3] : ""); // 최종거래일 또는 당일자

        }
        await scwin.getRsnCd();

        // alert( "Isur_cd =  " +Isur_cd + "\n"  + " Isur_nm = " + Isur_nm + "\n" + "  Secugrp_id = " + Secugrp_id + "\n" +
        //         "Mkt_id =  " +Mkt_id + "\n" + " fr_bz_procs_no = " + fr_bz_procs_no+ "\n"  ) ;

        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete); // 삭제
        buttonSet.setDsclInfo(btn_Dscl, scwin.dscl); // 안내문작성

        buttonSet.setCopyInfo(btn_Search, scwin.getIsuCd, btn_Save); // 조회

        edt_Dd.setValue(scwin.Dd);
        if (scwin.fr_bz_procs_no !== "") {
            // Provider화면 에서 넘겨받은 업무처리번호가 ""가 아니라면 신규작성으로 간주한다.
            edt_Dd.setReadOnly(true);
            await scwin.search();
        } else {
            edt_Dd.setReadOnly(false);
            await scwin.newOnload(); // 신규작성시 호출

        }

        /* 기존 : 로그인자의 부서 소속을 기준으로 한 시장구분코드가 9(시장전체공통)인 경우 달력이 표기
              수정 : 달력 전체 미표시로 수정 */
        // if(fr_MktId != '9'){
        btn_Dd.hide();
        img_STRT_DD.hide();
        img_LIST_DD.hide();
        btn_deleteRow.hide();
        // }

        $c.libRoundPanel.PanelToGroupBox(panel_3);
        $c.libRoundPanel.PanelToGroupBox(panel_1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05938.onpageload" });
    }
};

/**
         * @method
         * @name onpageunload
         * @description 화면 언로드 시 정리 처리
         * @returns {void}
         * @hidden N
         */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name trs_OnFail
 * @description On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_OnFail = function() {
    try {
        $c.lc.fn_alertMsg('F');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05938.trs_OnFail" });
    }
};

/**
 * @method
 * @name trs_OnSuccess
 * @description On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_OnSuccess = async function() {
    try {
        scwin.delYn = false;
        $c.lc.fn_alertMsg('S');
        if (buttonSet.status === "D") {
            // 삭제처리의 응답인 경우
            await $c.win.closePopup();
        } else {
            await scwin.search();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05938.trs_OnSuccess" });
    }
};

/**
 * @method
 * @name dts_Mst_OnLoadCompleted
 * @description dts_Mst 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Mst_OnLoadCompleted = function(rowcount) {
    try {
        if (scwin.fr_bz_procs_no === "") {
            dts_Mst.insertRow();
        }

        // 신규처리에 의한 조회인지,  수정에 의한 조회인지를 구별
        if (scwin.fr_bz_procs_no === "") {
            buttonSet.setInsertStatus();
        } else {
            $c.stf.setButtonSetWithDate(edt_DelistDd, false);
        }
        scwin.isFirstLoad = true;
        if (scwin.fr_bz_procs_no === "") {
            cmb_Rsn_Cd.BindColVal = "690020";
            txb_GrndRegulNm.setValue(dts_Rsn.getCellData(cmb_Rsn_Cd.getSelectedIndex() + 1, "REGL"));
        } else {
            cmb_Rsn_Cd.BindColVal = dts_Mst.getCellData(dts_Mst.getRowPosition(), "DELIST_RSN_CD");
        }
        scwin.isFirstLoad = false;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05938.dts_Mst_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05938.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name img_DelistDd_onclick
 * @description img_DelistDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_DelistDd_onclick = function() {
    try {
        txa_Remk.Text = "";
        edt_DelistDd.focus();
        popUpCalendar2(edt_DelistDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05938.img_DelistDd_onclick" });
    }
};

/**
 * @method
 * @name cmb_Rsn_Cd_onselchange2
 * @description cmb Rsn Cd onselchange2 처리
 * @returns {void}
 * @hidden N
 */
scwin.cmb_Rsn_Cd_onselchange2 = function() {
    try {
        if (scwin.isFirstLoad) return;
        txb_GrndRegulNm.setValue(dts_Rsn.getCellData(cmb_Rsn_Cd.getSelectedIndex() + 1, "REGL"));
        // alert(dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "CODE") + "\n" + dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "NAME")+ "\n" + dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "REGL")) ;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05938.cmb_Rsn_Cd_onselchange2" });
    }
};

/**
 * @method
 * @name cmb_Rsn_Cd_OnSelected
 * @description cmb Rsn Cd On Selected 처리
 * @returns {void}
 * @hidden N
 */
scwin.cmb_Rsn_Cd_OnSelected = function() {

};

/**
 * @method
 * @name btn_Dd_onclick
 * @description btn_Dd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Dd_onclick = function() {
    try {
        if (scwin.fr_bz_procs_no !== "") return;
        popUpCalendar2(edt_Dd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05938.btn_Dd_onclick" });
    }
};

/**
 * @method
 * @name dts_Isu_OnLoadCompleted
 * @description dts_Isu 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Isu_OnLoadCompleted = function(rowcount) {
    try {
        let count = dts_Isu.getRowCount();
        dts_Isu.setBroadcast(false);
        for (let i = 1; i < count + 1; i++) {
            dts_Isu.setCellData(i, "ELW_RGHT_TP_KIND_CD", 'F');
        }
        dts_Isu.setBroadcast(true, true);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05938.dts_Isu_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_deleteRow_onclick
 * @description 「행삭제」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_deleteRow_onclick = function() {
    try {
        if (confirm('선택한 종목을 삭제하시겠습니까?')) {
            let count = dts_Isu.getRowCount();
            dts_Isu.setBroadcast(false);
            for (let i = count; i > 0; i--) {
                if (dts_Isu.getCellData(i, "ELW_RGHT_TP_KIND_CD") === 'T') {
                    dts_Isu.removeRow(i);
                    scwin.delYn = true;
                }
            }
            dts_Isu.setBroadcast(true, true);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05938.btn_deleteRow_onclick" });
    }
};

/**
 * @method
 * @name edt_DelistDd_OnKillFocus
 * @description edt_DelistDd 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.edt_DelistDd_OnKillFocus = function() {
    try {
        let cnt = dts_Isu.getRowCount();
        txa_Remk.Text = "상기 " + cnt + "종목의 주식워런트 증권은 직전 1개월간 누적거래량이 상장증권수의 1%에 미달하는 거래부진종목으로서 LP가 전부보유한 사실이 ";
        txa_Remk.Text += "확인되어 " + edt_DelistDd.getValue().substring(0, 4) + "년 ";
        txa_Remk.Text += edt_DelistDd.getValue().substring(4, 6) + "월 ";
        txa_Remk.Text += edt_DelistDd.getValue().substring(6, 8) + "일에 상장폐지됨을 알려드립니다.";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05938.edt_DelistDd_OnKillFocus" });
    }
};

/**
 * @method
 * @name img_STRT_DD_onclick
 * @description img_STRT_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_STRT_DD_onclick = function() {
    try {
        popUpCalendar2(edt_STRT_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05938.img_STRT_DD_onclick" });
    }
};

/**
 * @method
 * @name img_LIST_DD_onclick
 * @description img_LIST_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_LIST_DD_onclick = function() {
    try {
        popUpCalendar2(edt_LIST_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05938.img_LIST_DD_onclick" });
    }
};

/**
 * @method
 * @name edt_Dd_OnKillFocus
 * @description edt_Dd 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.edt_Dd_OnKillFocus = async function() {
    try {
        await scwin.setDate();
        edt_END_DD.setValue(edt_Dd.getValue());
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05938.edt_Dd_OnKillFocus" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name getIsuCd
 * @description get Isu Cd 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getIsuCd = async function() {
    if (edt_Dd.text.length !== 8) {
        await $c.win.alert("[거래부진 폐지일]을 정확히 입력하세요.");
        return false;
    }
    if (edt_STRT_DD.text.length !== 8) {
        await $c.win.alert("[거래시작일]을 정확히 입력하세요.");
        return false;
    }
    if (edt_LIST_DD.text.length !== 8) {
        await $c.win.alert("[상장제한일]을 정확히 입력하세요.");
        return false;
    }
    url += "&{P}PROC_DD=" + edt_Dd.getValue();
    url += "&{P}STRT_DD=" + edt_STRT_DD.getValue();
    url += "&{P}LIST_DD=" + edt_LIST_DD.getValue();
    const sbmOptions = {
        id : "sbm_dts_Isu",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_Isu=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    if (scwin.fr_bz_procs_no !== "") {
        url += "&SCREN_ID=" + "ULDSTF05938.xml";
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        const sbmOptions = {
            id : "sbm_dts_Mst",
            action : "/Delisting.do",
            ref : "",
            target : "dts_Mst=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const sbmOptions2 = {
            id : "sbm_dts_Isu",
            action : "/Delisting.do",
            ref : "",
            target : "dts_Isu=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};

/**
 * @method
 * @name newOnload
 * @description new Onload 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.newOnload = async function() {
    url += "&SCREN_ID=" + "ULDSTF05938.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    // dts_Mst.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DELLIST_MST_INOUT";
    const sbmOptions = {
        id : "sbm_dts_Mst",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Mst=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    edt_Dd.setValue($c.ut.cGetToday("yyyymmdd"));
    edt_END_DD.setValue(edt_Dd.getValue());
    await scwin.setDate();
    await scwin.getIsuCd();
};

/**
 * @method
 * @name getRsnCd
 * @description get Rsn Cd 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getRsnCd = async function() {
    const sbmOptions = {
        id : "sbm_dts_Rsn",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_Rsn=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name duplicateCheck
 * @description duplicate Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.duplicateCheck = async function() {
    let Isus = "";
    if (dts_Isu.getRowCount() === 0) return false;
    for (let i = 1; i <= dts_Isu.getRowCount(); i++) {
        Isus += dts_Isu.getCellData(i, "ISU_CD") + ",";
    }
    const sbmOptions = {
        id : "sbm_dts_DUP_CHK",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_DUP_CHK=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    if (dts_DUP_CHK.getRowCount() > 0) {
        btn_deleteRow.show("");
        await $c.win.alert("'" + dts_DUP_CHK.getCellData(1, "ISU_CD") + "'" + " 종목이 \n" + "'" + dts_DUP_CHK.getCellData(1, "DELIST_RSN_NM") + "'" + " 사유로 저장되어 있습니다.");
        return true;
    } else {
        btn_deleteRow.hide();
    }
    return false;
};

/**
 * @method
 * @name saveTrs
 * @description 매매거래정지종목은 매번 업무처리 번호를 세팅함
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveTrs = async function() {
    // 매매거래정지종목은 매번 업무처리 번호를 세팅함
    // 종목별 변경이 있을수 있기 때문
    for (let i = 1; i <= dts_Isu.getRowCount(); i++) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        //
        // ********************************************************************

        /*ORG SRC: dts_Isu.NameString(i, "BZ_PROCS_NO") = fr_bz_procs_no;*/
        X = scwin.fr_bz_procs_no;
    }

    // ELW는 항상  종목별기준으로 처리함
    // 1 : 종목별 , 2 : 법인별

    dts_Mst.setCellData(dts_Mst.getRowPosition(), "MKTACT_APPL_OBJ_TP_CD", "1");
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "DELIST_RSN_CD", dts_Rsn.getCellData(cmb_Rsn_Cd.getSelectedIndex() + 1, "CODE"));
    let vScrenProcsTpCD = SCREN_PROCS_TP_CD_03;
    if (scwin.trsIdx === TRS_IDX_INSERT) vScrenProcsTpCD = SCREN_PROCS_TP_CD_02;

    else if (scwin.trsIdx === TRS_IDX_DELETE) vScrenProcsTpCD = SCREN_PROCS_TP_CD_04;
    trs.KeyName = "toinb_dataid4";
    // [전환검토] trs.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     TRS_IDX : scwin.trsIdx,
    //     BZ_PROCS_NO : scwin.fr_bz_procs_no,
    //     COUNT : "2",
    //     LIST_BZ_TP_CD : LIST_BZ_TP_CD_314 + ",DIV_IDX[0]=" + DIV_IDX_DELLIST_MST + ",DIV_IDX[1]=" + DIV_IDX_DELLIST_DTL
    // };
    const sbmOptions = {
        id : "sbm_trs",
        action : "/Delisting.do",
        ref : "dts_Mst,dts_Isu",
        target : "trs=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name elwInst
 * @description elw Inst 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.elwInst = async function() {
    const sbmOptions = {
        id : "sbm_dts_ElwInst",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_ElwInst=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name setDate
 * @description set Date 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setDate = async function() {
    url += "&{P}DATE1=" + scwin.getStrtDate();
    url += "&{P}DATE2=" + scwin.getListDate();
    const sbmOptions = {
        id : "sbm_dts_date",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_date=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    for (let i = 1; i <= dts_date.getRowCount(); i++) {
        if (dts_date.getCellData(i, 'CD_ID') === '1') {
            edt_STRT_DD.setValue(dts_date.getCellData(i, 'VALUE'));
        } else if (dts_date.getCellData(i, 'CD_ID') === '2') {
            edt_LIST_DD.setValue(dts_date.getCellData(i, 'VALUE'));
        }
    }
};

