///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (dts_Isu.getRowCount() === 0) {
        await $c.win.alert("[상장폐지종목]을 선택하세요.");
        return false;
    }
    if (!$c.lc.checkDdTm("DD", edt_DelistDd, "상장폐지", false)) return false;
    if (!$c.stf.checkEmptyValue(txb_GrndRegulNm, "근거규정")) return false;
    if (!$c.stf.checkMaxLength(txb_GrndRegulNm, 200, "근거규정")) return false;
    if (!$c.stf.checkMaxLength(txa_Remk, 2000, "기타")) return false;
    if (await scwin.duplicateCheck()) return false;
    return true;
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess('I')) return;
        scwin.fr_bz_procs_no = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
        if (scwin.fr_bz_procs_no.length !== 14) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            scwin.trsIdx = TRS_IDX_INSERT;
            dts_Mst.setCellData(dts_Mst.getRowPosition(), "BZ_PROCS_NO", scwin.fr_bz_procs_no);
            dts_Mst.setCellData(dts_Mst.getRowPosition(), "ISUR_CD", "99999");
            await scwin.saveTrs();
        }
    }
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    if (await scwin.checkForm()) {
        scwin.trsIdx = TRS_IDX_UPDATE;
        if (!$c.lc.fn_isProcess('U')) return;
        await scwin.saveTrs();
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    if (!$c.lc.fn_isProcess('D')) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.trsIdx = TRS_IDX_DELETE;
    await scwin.saveTrs();
};

/**
 * @method
 * @name dscl
 * @description dscl 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dscl = async function() {
    if (await scwin.duplicateCheck()) return;

    // 수정한 것이 있으면 체크 됨.(종목제외)
    if ($c.cp.isModified(dts_Mst) || $c.cp.isModified(dts_Rsn) || scwin.delYn === true) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0022", ""));
        return;
    }
    const OldGet = scwin.getPar;
    const OldSet = scwin.setPar;
    await scwin.elwInst();
    // dts_DISC.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
    let cont = 1;
    dts_DISC.setBroadcast(false);
    for (let i = 1; i <= dts_ElwInst.getRowCount(); i++) {
        let pLpMbtNm = "";
        let pIsuNm = "";
        let pCheck = false;
        let pcount = 0;
        const pLenStr = 0;
        let cnt = 1;
        for (let k = 1; k <= dts_Isu.getRowCount(); k++) {
            if (dts_ElwInst.getCellData(i, "VALUE") === dts_Isu.getCellData(k, "INFO_ISUR_CD")) {
                pLpMbtNm = dts_ElwInst.getCellData(i, "TEXT");
                if (pcount > 0) {
                    pIsuNm = pIsuNm + ",";
                }
                if (pcount % 4 === 0 && pcount !== 0) pIsuNm = pIsuNm + "\n" + dts_Isu.getCellData(k, "ISU_NM");

                else pIsuNm = pIsuNm + dts_Isu.getCellData(k, "ISU_NM");
                pcount++;
                pCheck = true;
            }
        }
        if (pCheck) {
            dts_DISC.insertRow();
            dts_DISC.setCellData(cont, "INFO_COM_NM", pLpMbtNm);
            dts_DISC.setCellData(cont, "ISU_NM", pIsuNm);
            cont++;
        }
    }
    dts_DISC.setBroadcast(true, true);
    scwin.getPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
        arr[0] = "68955F";
        arr[1] = scwin.fr_bz_procs_no;
        arr[2] = "99999";
        arr[3] = '1';
        arr[4] = '';
        arr[5] = '거래 부진에 의한 상장폐지';
        $c.stf.copyDataSet(dts_Isu, param_dts_isu);
        $c.stf.copyDataSet(dts_Mst, param_dts_mst);
        $c.stf.copyDataSet(dts_DISC, param_dts2);
        param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "DELIST_RSN_NM", cmb_Rsn_Cd.getText());
        //    param_dts_mst.NameString(param_dts_mst.RowPosition, "COM_NM") = p_Isur_nm ;    //발행사명

        return arr.length;
    };
    scwin.setPar = function(arr) {

    };
    const wth = 740 + 5;
    const hgt = 790 + 30;
    const pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    const options = {
        id: "ULDSTF92024",
        title: "공시안내문작성",
        type: "browserPopup",
        width: wth,
        height: hgt,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/listingcommon/ULDSTF92024.gfm", options);
    scwin.getPar = OldGet;
    scwin.setPar = OldSet;
};

/**
 * @method
 * @name getStrtDate
 * @description get Strt Date 처리
 * @returns {void}
 * @hidden N
 */
scwin.getStrtDate = function() {
    let yyyymmdd = edt_Dd.getValue();
    let yyyy = yyyymmdd.substring(0, 4);
    let mm = yyyymmdd.substring(4, 6);
    let dd = yyyymmdd.substring(6, 8);
    if (mm === 01) {
        mm = 12;
        yyyy = yyyy - 1;
    } else {
        mm = mm - 1;
    }
    return '' + yyyy + $c.ut.cGetZero(mm, 2) + dd;
};

/**
 * @method
 * @name getListDate
 * @description get List Date 처리
 * @returns {void}
 * @hidden N
 */
scwin.getListDate = function() {
    let yyyymmdd = edt_Dd.getValue();
    let yyyy = yyyymmdd.substring(0, 4);
    let mm = yyyymmdd.substring(4, 6);
    let dd = yyyymmdd.substring(6, 8);
    if (mm === 02) {
        mm = 12;
        yyyy = yyyy - 1;
    } else if (mm === 01) {
        mm = 11;
        yyyy = yyyy - 1;
    } else {
        mm = mm - 2;
    }
    return '' + yyyy + $c.ut.cGetZero(mm, 2) + dd;
};

